mapper.select:
SELECT ranked.id, ranked.nid, ranked.note_uid, ranked.uid, ranked.pid, ranked.reply_id, ranked.reply_uid, ranked.level, ranked.sort, ranked.content, ranked.like_count, ranked.two_comment_count, ranked.creator, ranked.create_time, ranked.updater, ranked.update_time FROM ( SELECT c.id, c.nid, c.note_uid, c.uid, c.pid, c.reply_id, c.reply_uid, c.level, c.sort, c.content, c.like_count, c.two_comment_count, c.creator, c.create_time, c.updater, c.update_time, ROW_NUMBER() OVER ( PARTITION BY c.pid ORDER BY c.like_count DESC, c.create_time DESC, c.id DESC ) AS reply_position FROM web_comment c WHERE c.pid IN
#{parentId}
) ranked WHERE ranked.reply_position <= #{limit} ORDER BY ranked.pid, ranked.reply_position

SELECT pid, COUNT(*) AS reply_count FROM web_comment WHERE pid IN
#{parentId}
GROUP BY pid
